// Package repo là tầng truy cập Postgres, được SINH TỰ ĐỘNG bởi sqlc từ:
//   - migrations/*.up.sql  -> cấu trúc bảng -> models.go (struct Hold, SeatInventory)
//   - queries/*.sql        -> từng câu SQL  -> holds.sql.go, seats.sql.go (mỗi câu một method)
//
// Mọi file .go trong thư mục này có dòng "Code generated by sqlc. DO NOT EDIT." đều KHÔNG được
// sửa tay: lần chạy `make sqlc` sau sẽ ghi đè. Muốn thêm/sửa query thì sửa queries/*.sql rồi
// chạy lại `make sqlc`. Riêng file doc.go này viết tay, sqlc không đụng tới.
//
// Cú pháp trong queries/*.sql:
//
//	-- name: GetHold :one      <- tên method Go + kiểu kết quả
//	-- Comment ở đây           <- được chép thành doc comment của method
//	SELECT * FROM holds WHERE id = $1;
//
// Kiểu kết quả:
//   - :one      -> trả về 1 dòng; không có dòng nào thì lỗi pgx.ErrNoRows
//   - :many     -> trả về slice nhiều dòng (rỗng nếu không có)
//   - :execrows -> chỉ trả về số dòng bị ảnh hưởng (int64)
//
// Tham số: $1, $2 là tham số theo vị trí; @ten_tham_so là tham số có tên. Khi query có từ hai
// tham số trở lên, sqlc gom chúng thành struct XxxParams (vd CreateHoldParams).
// Cách map kiểu Postgres -> Go (uuid -> uuid.UUID, timestamptz -> time.Time) cấu hình trong
// sqlc.yaml.
//
// Các thành phần sinh ra:
//   - DBTX (db.go): interface chung cho *pgxpool.Pool và pgx.Tx, nên cùng một Queries chạy được
//     cả ngoài lẫn trong transaction.
//   - Queries (db.go): struct chứa mọi method query. New(pool) tạo Queries chạy trên pool;
//     q.WithTx(tx) tạo bản sao chạy bên trong transaction tx.
//   - Querier (querier.go): interface liệt kê mọi method, tiện cho việc mock khi test.
//
// Ví dụ dùng (xem internal/service/service.go):
//
//	q := repo.New(pool)
//	h, err := q.GetHold(ctx, holdID)
//	if errors.Is(err, pgx.ErrNoRows) { /* không tìm thấy */ }
package repo
